{'role': 'assistant', 'tool_calls': [{'id': 'toolu_e3R3NTwI3Dh9m2twEh3iCCNE', 'name': 'Write', 'arguments': {'content': '"""Wiz Cloud Security posture collector.

Builds a single payload for the Cloud Security dashboard:
  * Open vulnerability findings broken down by severity.
  * CSPM (Cloud Configuration) issues broken down by severity.
  * A per-cloud-account breakdown of both, so teams can see which
    subscriptions carry the most risk.

Global severity totals use the same validated Wiz GraphQL fields the rest of
the app relies on. The per-account breakdown filters by the account's Wiz id
(``subscriptionId``); if a tenant's schema doesn't support that filter the
account section degrades to ``supported: false`` rather than failing the whole
collection, so the severity totals always render.
"""
from __future__ import annotations

import json
import logging
from typing import Any

from app.connectors.wiz import WizConnector
from app.queries.wiz import _safe

logger = logging.getLogger(__name__)

_SEVERITIES = ("critical", "high", "medium", "low")
# Per-account breakdown only fetches critical + high. Each severity is a
# separate (expensive) findings-count query against Wiz, and the dashboard's
# account table only needs the actionable severities. Medium/low stay on the
# global panels. This keeps the per-account walk under Wiz's query-cost limit.
_ACCOUNT_SEVERITIES = ("critical", "high")

VULN_BY_SEVERITY_QUERY = """
query VulnsBySeverity {
  critical: vulnerabilityFindings(first: 0, filterBy: { status: [OPEN, IN_PROGRESS], severity: [CRITICAL] }) { totalCount }
  high:     vulnerabilityFindings(first: 0, filterBy: { status: [OPEN, IN_PROGRESS], severity: [HIGH] }) { totalCount }
  medium:   vulnerabilityFindings(first: 0, filterBy: { status: [OPEN, IN_PROGRESS], severity: [MEDIUM] }) { totalCount }
  low:      vulnerabilityFindings(first: 0, filterBy: { status: [OPEN, IN_PROGRESS], severity: [LOW] }) { totalCount }
}
"""

CSPM_BY_SEVERITY_QUERY = """
query CspmBySeverity {
  critical: issues(first: 0, filterBy: { status: [OPEN, IN_PROGRESS], type: [CLOUD_CONFIGURATION], severity: [CRITICAL] }) { totalCount }
  high:     issues(first: 0, filterBy: { status: [OPEN, IN_PROGRESS], type: [CLOUD_CONFIGURATION], severity: [HIGH] }) { totalCount }
  medium:   issues(first: 0, filterBy: { status: [OPEN, IN_PROGRESS], type: [CLOUD_CONFIGURATION], severity: [MEDIUM] }) { totalCount }
  low:      issues(first: 0, filterBy: { status: [OPEN, IN_PROGRESS], type: [CLOUD_CONFIGURATION], severity: [LOW] }) { totalCount }
}
"""

CLOUD_ACCOUNTS_QUERY = """
query CloudAccounts($first: Int, $after: String) {
  cloudAccounts(first: $first, after: $after) {
    nodes {
      id
      name
      cloudProvider
      externalId
      status
    }
    pageInfo { hasNextPage endCursor }
    totalCount
  }
}
"""

# How many cloud accounts to score per GraphQL request. Each account adds 8
# aliased totalCount sub-queries (4 vuln severities + 4 CSPM severities). Wiz
# cost-limits a single request: 2 accounts (16 aliases, 8 of them counting the
# multi-million-row vulnerability index) succeed, but 3 accounts (24 aliases)
# trips a 429 cost limit. So we cap at 2 and pace requests, with backoff in the
# connector handling any transient 429s.
_ACCOUNT_BATCH_SIZE = 2
# Seconds to wait between account batches to stay under Wiz's rate limit. This
# runs on a slow background collector, so pacing has no user-facing impact.
_BATCH_DELAY_SECONDS = 0.5


def _sev_dict_from(data: dict | None, prefix: str = "") -> dict[str, int]:
    data = data or {}
    out: dict[str, int] = {}
    for sev in _SEVERITIES:
        key = f"{prefix}{sev}" if prefix else sev
        out[sev] = _safe(data, key, "totalCount")
    out["total"] = sum(out[s] for s in _SEVERITIES)
    return out


async def _global_vuln_by_severity(client: WizConnector) -> dict[str, int]:
    resp = await client.query(VULN_BY_SEVERITY_QUERY)
    return _sev_dict_from(resp.get("data"))


async def _global_cspm_by_severity(client: WizConnector) -> dict[str, int]:
    resp = await client.query(CSPM_BY_SEVERITY_QUERY)
    return _sev_dict_from(resp.get("data"))


async def _list_cloud_accounts(
    client: WizConnector, max_pages: int = 10, page_size: int = 100
) -> list[dict[str, Any]]:
    """Enumerate Wiz cloud accounts (subscriptions/projects per provider)."""
    accounts: list[dict[str, Any]] = []
    cursor: str | None = None
    for _ in range(max_pages):
        variables: dict[str, Any] = {"first": page_size}
        if cursor:
            variables["after"] = cursor
        resp = await client.query(CLOUD_ACCOUNTS_QUERY, variables)
        if "errors" in resp:
            logger.warning(
                "Wiz cloudAccounts query errors: %s", json.dumps(resp["errors"])[:300]
            )
            break
        data = _safe(resp, "data", "cloudAccounts", default={}) or {}
        for node in data.get("nodes") or []:
            accounts.append(
                {
                    "id": node.get("id") or "",
                    "name": node.get("name") or node.get("id") or "Unknown",
                    "cloud_provider": node.get("cloudProvider") or "",
                    "external_id": node.get("externalId") or "",
                    "status": node.get("status") or "",
                }
            )
        page_info = data.get("pageInfo") or {}
        if not page_info.get("hasNextPage"):
            break
        cursor = page_info.get("endCursor")
    return accounts


def _account_batch_query(batch: list[dict[str, Any]]) -> str:
    """Build one aliased query scoring several accounts' severities at once.

    Verified Wiz filter fields (probed against the live tenant):
      * vulnerabilityFindings -> ``subscriptionExternalId`` (the account's
        cloud-native external id, e.g. an AWS account number).
      * issues -> ``cloudAccountOrCloudOrganizationId`` (the Wiz account id).

    Values are inlined (JSON-encoded) so the query carries no typed variables.
    Accounts without an external id skip the vuln sub-queries (those parse back
    to 0), but still get CSPM counts via their Wiz id.
    """
    parts: list[str] = []
    for i, acct in enumerate(batch):
        ext = acct.get("external_id") or ""
        aid = acct.get("id") or ""
        if ext:
            ext_lit = json.dumps(ext)
            for sev in _SEVERITIES:
                parts.append(
                    f'a{i}_vuln_{sev}: vulnerabilityFindings(first: 0, filterBy: '
                    f'{{ status: [OPEN, IN_PROGRESS], severity: [{sev.upper()}], '
                    f'subscriptionExternalId: [{ext_lit}] }}) {{ totalCount }}'
                )
        if aid:
            aid_lit = json.dumps(aid)
            for sev in _SEVERITIES:
                parts.append(
                    f'a{i}_cspm_{sev}: issues(first: 0, filterBy: '
                    f'{{ status: [OPEN, IN_PROGRESS], type: [CLOUD_CONFIGURATION], '
                    f'severity: [{sev.upper()}], cloudAccountOrCloudOrganizationId: [{aid_lit}] }}) {{ totalCount }}'
                )
    body = "\n  ".join(parts)
    return f"query AccountBatch {{\n  {body}\n}}"


async def _score_account_batch(
    client: WizConnector, batch: list[dict[str, Any]]
) -> list[dict[str, Any]] | None:
    """Score a batch of accounts. Returns None if the query errored."""
    resp = await client.query(_account_batch_query(batch))
    if "errors" in resp:
        logger.warning(
            "Wiz account batch query errors: %s", json.dumps(resp["errors"])[:300]
        )
        return None
    data = resp.get("data") or {}
    out: list[dict[str, Any]] = []
    for i, acct in enumerate(batch):
        out.append(
            {
                **acct,
                "vuln": _sev_dict_from(data, prefix=f"a{i}_vuln_"),
                "cspm": _sev_dict_from(data, prefix=f"a{i}_cspm_"),
            }
        )
    return out


async def query_cloud_security(
    client: WizConnector, max_accounts: int = 200
) -> dict[str, Any]:
    """Top-level Cloud Security collector. Shaped for /api/cloud-security."""
    from datetime import datetime, timezone

    vuln = await _global_vuln_by_severity(client)
    cspm = await _global_cspm_by_severity(client)

    accounts_meta = [a for a in await _list_cloud_accounts(client) if a.get("id")]
    accounts_meta = accounts_meta[:max_accounts]
    accounts: list[dict[str, Any]] = []
    batches_attempted = 0
    batches_ok = 0

    import asyncio

    for start in range(0, len(accounts_meta), _ACCOUNT_BATCH_SIZE):
        batch = accounts_meta[start : start + _ACCOUNT_BATCH_SIZE]
        batches_attempted += 1
        if start > 0:
            await asyncio.sleep(_BATCH_DELAY_SECONDS)
        try:
            scored = await _score_account_batch(client, batch)
        except Exception:
            logger.warning("Wiz account batch failed (start=%d)", start, exc_info=True)
            scored = None
        if scored is None:
            continue
        batches_ok += 1
        accounts.extend(scored)

    # Only mark the section unsupported if we had accounts but every batch
    # failed (systemic schema/permission issue), so the frontend can degrade.
    account_breakdown_supported = not (batches_attempted > 0 and batches_ok == 0)
    # Drop accounts with no open findings at all to keep the table focused.
    accounts = [a for a in accounts if a["vuln"]["total"] or a["cspm"]["total"]]

    # Highest combined critical+high risk first.
    accounts.sort(
        key=lambda a: (
            a["vuln"]["critical"] + a["cspm"]["critical"],
            a["vuln"]["high"] + a["cspm"]["high"],
            a["vuln"]["total"] + a["cspm"]["total"],
        ),
        reverse=True,
    )

    return {
        "last_synced": datetime.now(timezone.utc).isoformat(),
        "vuln_by_severity": vuln,
        "cspm_by_severity": cspm,
        "totals": {
            "vulnerabilities": vuln["total"],
            "cspm_issues": cspm["total"],
            "critical": vuln["critical"] + cspm["critical"],
            "high": vuln["high"] + cspm["high"],
        },
        "accounts": accounts,
        "account_count": len(accounts),
        "account_breakdown_supported": account_breakdown_supported,
    }
